import urllib.request
import urllib.error
import time

class RateLimitError(Exception):
    pass

class ServerError(Exception):
    pass

class ClientError(Exception):
    pass

class ConnectionError(Exception):
    pass

class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path):
        url = self.base_url + path
        # Try for 429: up to 3 retries with exponential backoff (0.5, 1, 2)
        # Try for 5xx: 1 retry after 1s
        # Try for network errors: 1 retry after 1s
        # 4xx (except 429): raise immediately

        # We need to handle different retry strategies. Let's structure it carefully.
        # For 429: max 3 retries (so total 4 attempts: initial + 3 retries)
        # For 5xx: max 1 retry (so total 2 attempts)
        # For network errors: max 1 retry (so total 2 attempts)

        # We'll track attempts separately for each error type.
        attempts_429 = 0
        attempts_5xx = 0
        attempts_network = 0

        while True:
            try:
                req = urllib.request.Request(url)
                response = urllib.request.urlopen(req, timeout=self.timeout)
                # Read the response body
                body = response.read().decode('utf-8')
                return body
            except urllib.error.HTTPError as e:
                code = e.code
                if code == 429:
                    attempts_429 += 1
                    if attempts_429 <= 3:
                        # Exponential backoff: 0.5, 1, 2
                        wait_time = 0.5 * (2 ** (attempts_429 - 1))
                        time.sleep(wait_time)
                        continue
                    else:
                        raise RateLimitError(f"Rate limited after {attempts_429} retries")
                elif 500 <= code < 600:
                    attempts_5xx += 1
                    if attempts_5xx <= 1:
                        time.sleep(1)
                        continue
                    else:
                        raise ServerError(f"Server error {code} after retry")
                elif 400 <= code < 500:
                    # 4xx except 429, raise immediately
                    raise ClientError(f"Client error {code}")
                else:
                    # Other HTTP errors, treat as unexpected
                    raise ClientError(f"HTTP error {code}")
            except urllib.error.URLError as e:
                attempts_network += 1
                if attempts_network <= 1:
                    time.sleep(1)
                    continue
                else:
                    raise ConnectionError(f"Connection error after retry: {e}")
            except Exception as e:
                # Other unexpected errors
                raise
